Hook.Script:
jsonEntry = system.newEntry();
jsonEntry.status = "failed";
jsonEntry.message = "TestConnection failed: " + error.toString();
jsonPayload = jsonEntry.toJSON();
work.result = jsonPayload;
try {
	sendCustomNotification("fds.testconnection", opEntry.getString("testId"), jsonPayload);
} catch (ex) {
	logmsg("ERROR", "Unable to send test connection notification: " + ex);
}

Script.parameter:
// Read the OpenLDAP connection settings supplied on the FDS Connection Settings page.
ldapUrl  = getProperty("target.ldap.url");
binddn   = getProperty("target.ldap.user");
bindpw   = getProperty("target.ldap.password");
base     = getProperty("target.ldap.searchBase", "");
useSSL   = "true".equalsIgnoreCase(getProperty("target.ldap.useSSL", "false"));
authMeth = getProperty("target.ldap.authMethod", "Simple");

jsonEntry = system.newEntry();

if (ldapUrl == null || ldapUrl.trim().length() == 0) {
	jsonEntry.status = "failed";
	jsonEntry.message = "No LDAP URL configured.";
} else {
	conn = null;
	try {
		// Build and open a short-lived LDAP connection in Lookup mode to validate the settings.
		conn = system.getConnector("ibmdi.LDAP");
		conn.setParam("ldapUrl", ldapUrl);
		conn.setParam("ldapAuthenticationMethod", authMeth);
		if (binddn != null) conn.setParam("ldapUsername", binddn);
		if (bindpw != null) conn.setParam("ldapPassword", bindpw);
		conn.setParam("ldapSearchBase", base);
		conn.setParam("ldapUseSSL", "" + useSSL);
		conn.setParam("ldapSearchScope", "base");
		conn.setParam("ldapSearchFilter", "(objectClass=*)");
		conn.initialize(null);
		conn.terminate();
		jsonEntry.status = "success";
	} catch (ex) {
		jsonEntry.status = "failed";
		jsonEntry.message = "Error connecting to OpenLDAP target: " + ldapUrl + " - " + ex;
		try { if (conn != null) conn.terminate(); } catch (ignore) {}
	}
}

// Return the status payload to the FDS user interface.
jsonPayload = jsonEntry.toJSON();
logmsg("INFO", "TestConnection result: " + jsonPayload);
work.result = jsonPayload;

// Signal completion to the FDS UI.
sendCustomNotification("fds.testconnection", opEntry.getString("testId"), jsonPayload);

Hook.Script:
tcb = task.getTCB();
tcb["$status"] = "failed";
tcb["$writeStatus"] = "failed";
tcb["$change"] = false;
tcb["$error"] = error;
try { logmsg("ERROR", "WriteToTarget failed: " + error.toString()); } catch (ex) {}

Script.parameter:
// Reference the Task Call Block and read what FDS is asking for.
tcb = task.getTCB();
typeOfEntry = tcb.getString("$typeOfEntry");
operation   = tcb.getString("$operation");
search      = tcb.getObject("$search");

// Default the return TCB attributes to a safe (failed / no change) state.
tcb["$change"] = false;
tcb["$writeStatus"] = "failed";
tcb["$status"] = "failed";
tcb["$error"] = null;

logmsg("INFO", "WriteToTarget: operation=" + operation + " typeOfEntry=" + typeOfEntry);

tcb = task.getTCB();
tcb["$status"] = "success";
tcb["$writeStatus"] = "unchanged";
tcb["$change"] = false;

tcb = task.getTCB();
tcb["$status"] = "success";
tcb["$writeStatus"] = "unchanged";
tcb["$change"] = false;

rdnAttr = getProperty("flow.person.rdn", "uid");
container = getProperty("flow.person.container", getProperty("target.ldap.searchBase", ""));
existing = work.getString("$dn");
if (existing == null || existing.length() == 0) {
	rdnVal = work.getString(rdnAttr);
	if (rdnVal != null && rdnVal.length() > 0) {
		dn = rdnAttr + "=" + rdnVal;
		if (container != null && container.length() > 0) dn = dn + "," + container;
		work["$dn"] = dn;
	}
}

