Configuration.parameter:
@SUBSTITUTE{javascript param = getProperty("target.ldap.binaryAttributes", null);
if (param === null) return "";
if (param.indexOf(",") > 0) atts = system.splitString(param, ",");
else if (param.indexOf("\n") > 0) atts = system.splitString(param, "\n");
else atts = system.splitString(param, " ");
pstr = "";
for (a in atts) pstr += a + "\n";
return pstr;}
